const keys = Object.keys(TERMS).sort((a, b) => b.length - a.length);
const byFirst = new Map();
for (const k of keys) {
  const c = k[0];
  if (!byFirst.has(c)) byFirst.set(c, []);
  byFirst.get(c).push(k);
}

export function convert(text) {
  const s = String(text ?? '');
  let out = '';
  for (let i = 0; i < s.length;) {
    const bucket = byFirst.get(s[i]);
    let hit = null;
    if (bucket) for (const k of bucket) if (s.startsWith(k, i)) { hit = k; break; }
    if (hit) { out += TERMS[hit]; i += hit.length; }
    else { out += CHARS[s[i]] ?? s[i]; i++; }
  }
  return out;
}
